"""8.31 item 3: weight history on Progress, Body: add, edit, delete with Undo, units, Food link, chart, backup, tip."""
import sys, os, json, datetime; sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from common import *
from playwright.sync_api import sync_playwright
EXPORT="(()=>{let out=null;const o=URL.createObjectURL;const a=HTMLAnchorElement.prototype.click;HTMLAnchorElement.prototype.click=function(){};URL.createObjectURL=function(bl){out=bl;return 'blob:x'};exportData();URL.createObjectURL=o;HTMLAnchorElement.prototype.click=a;return out?out.text():null})()"
BW="JSON.parse(localStorage.getItem('monk_bodyweight_v1')||'{}')"
ROWS="[...document.querySelectorAll('#progView .bw-row')].map(r=>[r.querySelector('.bw-d').innerText,r.querySelector('.bw-v').innerText])"
def body(pg): pg.evaluate("goTab('calendar');setProgView('body');scrollTo(0,0)"); pg.wait_for_timeout(300)
def save(pg,d,v):
    pg.evaluate("bwPickDate('%s')"%d); pg.fill('#bwVal',str(v)); pg.click('#bwForm .bw-save'); pg.wait_for_timeout(250)
with sync_playwright() as p:
    b=p.chromium.launch()
    ctx,pg,errs=page(b,360,700)
    pg.evaluate("localStorage.setItem('monk_bodyweight_v1',JSON.stringify({'2026-11-01':180}));loadFoodData();setRunUnits('mi')")
    go(pg,'calendar'); pg.evaluate("setProgView('lifts')"); pg.wait_for_timeout(200)
    t=pg.evaluate("(()=>{const b=[...document.querySelectorAll('#progTiles .prog-tile')].find(e=>/Add your weight/.test(e.innerText));return b?[b.tagName,b.innerText,Math.round(b.getBoundingClientRect().height)]:null})()")
    check('Progress stat card None yet is a button, 44 px or more', t and t[0]=='BUTTON' and 'None yet' in t[1] and t[2]>=44, t)
    pg.click('#progTiles .prog-tile-btn'); pg.wait_for_timeout(400)
    check('stat card opens the Add weight form on Body', pg.evaluate("_progView==='body' && document.activeElement.id==='bwVal' && !!document.getElementById('bwForm').offsetParent"))
    f=pg.evaluate("[document.getElementById('bwDate').value,document.getElementById('bwDate').max,document.getElementById('bwVal').value,document.querySelector('label[for=bwVal]').innerText]")
    check('form: date defaults to today, no later than today, weight in lb', f==['2026-11-19','2026-11-19','','Weight (lb)'], f)
    sz=pg.evaluate("[...document.querySelectorAll('#bwDate,#bwVal,#bwForm .bw-save')].map(e=>Math.round(e.getBoundingClientRect().height))")
    check('form fields and Save are 44 px', all(x>=44 for x in sz), sz)
    old=pg.evaluate("document.getElementById('progView').innerText")
    pg.fill('#bwVal','182.4'); pg.click('#bwForm .bw-save'); pg.wait_for_timeout(300)
    check('add today: stored in lb on the shared store', pg.evaluate(BW).get('2026-11-19')==182.4, pg.evaluate(BW))
    check('list newest first, date and weight', pg.evaluate(ROWS)[:2]==[['Nov 19','182.4 lb'],['Nov 1','180 lb']], pg.evaluate(ROWS))
    acts=pg.evaluate("[...document.querySelectorAll('#progView .bw-row')][0].querySelectorAll('button').length && [...document.querySelectorAll('#progView .bw-act')].map(e=>[e.innerText,Math.round(e.getBoundingClientRect().height),Math.round(e.getBoundingClientRect().width)])")
    check('each row has Edit and Delete, 44 px', acts[:2]==[['Edit',44,acts[0][2]],['Delete',44,acts[1][2]]] and all(a[2]>=44 for a in acts), acts[:4])
    check('stat card now shows a change', pg.evaluate("document.getElementById('progTiles').innerText").count('lbs')>=1)
    w1=pg.evaluate("document.querySelector('.bw-week').innerText"); c1=pg.evaluate("document.querySelectorAll('#progBodyChart-sum, svg[aria-labelledby=\"progBodyChart-sum\"] circle').length")
    save(pg,'2026-10-29',185)
    check('add three weeks ago', pg.evaluate(BW).get('2026-10-29')==185 and ['Oct 29','185 lb'] in pg.evaluate(ROWS), pg.evaluate(ROWS))
    s2=pg.evaluate("document.getElementById('progBodyChart-sum').innerText")
    check('chart summary uses all entries', 'from 185 to 182.4' in s2, s2)
    # edit
    pg.click("#progView .bw-row:has-text('Oct 29') .bw-act:has-text('Edit')"); pg.wait_for_timeout(200)
    e=pg.evaluate("[document.getElementById('bwDate').value,document.getElementById('bwVal').value,document.getElementById('bwMsg').innerText]")
    check('Edit puts the row back in the form and shows the old value', e[0]=='2026-10-29' and e[1]=='185' and 'This date has 185 lb' in e[2], e)
    pg.fill('#bwVal','184'); pg.click('#bwForm .bw-save'); pg.wait_for_timeout(250)
    check('saving an edited date replaces it, one weight per date', pg.evaluate(BW).get('2026-10-29')==184 and sum(1 for r in pg.evaluate(ROWS) if r[0]=='Oct 29')==1)
    pg.evaluate("bwPickDate('2026-11-19')"); pg.wait_for_timeout(100)
    check('picking a date that has a weight shows it in the field first', pg.evaluate("document.getElementById('bwVal').value")=='182.4')
    # delete and undo
    pg.click("#progView .bw-row:has-text('Oct 29') .bw-act:has-text('Delete')"); pg.wait_for_timeout(200)
    tb=pg.evaluate("(()=>{const t=document.getElementById('swapToast');return [t.style.display,t.innerText,Math.round(t.querySelector('button').getBoundingClientRect().height)]})()")
    check('Delete removes the row at once, no dialog, Undo bar shows', '2026-10-29' not in pg.evaluate(BW) and tb[0]=='flex' and 'Undo' in tb[1] and tb[2]>=44, tb)
    check('chart updates after delete', 'from 185' not in pg.evaluate("document.getElementById('progBodyChart-sum').innerText"))
    pg.click('#swapToast .swap-undo'); pg.wait_for_timeout(200)
    check('Undo brings it back', pg.evaluate(BW).get('2026-10-29')==184 and ['Oct 29','184 lb'] in pg.evaluate(ROWS))
    pg.click("#progView .bw-row:has-text('Oct 29') .bw-act:has-text('Delete')"); pg.wait_for_timeout(100)
    pg.clock.run_for(4500)
    check('Undo bar still up at 4.5 s', pg.evaluate("document.getElementById('swapToast').style.display")=='flex')
    pg.clock.run_for(800)
    check('Undo bar gone after 5 s, delete stays', pg.evaluate("document.getElementById('swapToast').style.display")=='none' and '2026-10-29' not in pg.evaluate(BW))
    pg.evaluate("bwUndoDelete()"); check('late undo does nothing', '2026-10-29' not in pg.evaluate(BW))
    save(pg,'2026-10-29',184)
    w2=pg.evaluate("document.querySelector('.bw-week').innerText")
    check('week to week line present and based on entries', 'This week averages 182.4 lb' in w2, [w1,w2])
    save(pg,'2026-11-12',186)
    w3=pg.evaluate("document.querySelector('.bw-week').innerText")
    check('week to week line updates when a past week is added', 'down 3.6 lb from last week' in w3, w3)
    # future and range
    pg.evaluate("document.getElementById('bwDate').value='2026-11-25'"); pg.fill('#bwVal','180'); pg.click('#bwForm .bw-save'); pg.wait_for_timeout(200)
    check('future date blocked with a plain message', '2026-11-25' not in pg.evaluate(BW) and 'not happened yet' in pg.evaluate("document.getElementById('bwMsg').innerText"), pg.evaluate("document.getElementById('bwMsg').innerText"))
    for v,ok in (('49',0),('701',0),('abc',0),('50',1),('700',1)):
        pg.evaluate("bwPickDate('2026-11-05')"); pg.fill('#bwVal',v) if v!='abc' else pg.evaluate("document.getElementById('bwVal').value=''"); pg.click('#bwForm .bw-save'); pg.wait_for_timeout(150)
        got=pg.evaluate(BW).get('2026-11-05'); msg=pg.evaluate("document.getElementById('bwMsg').innerText")
        check('lb %s %s'%(v,'accepted' if ok else 'rejected'), (got==float(v)) if ok else (got in (None,50.0,700.0) and ('between 50 and 700 lb' in msg or 'Add your weight' in msg)), [got,msg])
    pg.evaluate("delete bodyweight['2026-11-05'];persistBodyweight();renderProgressHome()")
    # kg
    pg.evaluate("weightUnit='kg';renderProgressHome()"); pg.wait_for_timeout(200)
    k=pg.evaluate("[document.querySelector('label[for=bwVal]').innerText, %s]"%ROWS)
    check('kg setting: form and list in kg', k[0]=='Weight (kg)' and ['Nov 19','82.7 kg'] in k[1], k)
    save(pg,'2026-11-10',80)
    check('kg entry stored as lb, shown as kg', abs(pg.evaluate(BW).get('2026-11-10')-176.4)<0.05 and ['Nov 10','80 kg'] in pg.evaluate(ROWS), [pg.evaluate(BW).get('2026-11-10'),pg.evaluate(ROWS)])
    save(pg,'2026-11-09',20); m=pg.evaluate("document.getElementById('bwMsg').innerText")
    check('kg 20 rejected with kg range', '2026-11-09' not in pg.evaluate(BW) and 'between 23 and 317 kg' in m, m)
    save(pg,'2026-11-09',318)
    check('kg 318 rejected', '2026-11-09' not in pg.evaluate(BW))
    check('kg chart summary in kg', ' kg' in pg.evaluate("document.getElementById('progBodyChart-sum').innerText"))
    pg.evaluate("weightUnit='lb';renderProgressHome()")
    # Food <-> Body
    pg.evaluate(FOOD_ON); go(pg,'food'); pg.fill('#foodWeighToday','181'); pg.evaluate("document.getElementById('foodWeighToday').dispatchEvent(new Event('change'))"); pg.wait_for_timeout(200)
    body(pg)
    check('weight entered on Food shows on Body', ['Nov 19','181 lb'] in pg.evaluate(ROWS), pg.evaluate(ROWS)[:2])
    save(pg,'2026-11-19',183)
    go(pg,'food')
    check('weight entered on Body shows on Food', pg.evaluate("document.getElementById('foodWeighToday').value")=='183')
    # chart labels
    body(pg)
    ov=pg.evaluate("(()=>{const t=[...document.querySelectorAll('svg[aria-labelledby=\"progBodyChart-sum\"] .ch-x')].map(e=>e.getBoundingClientRect());for(let i=1;i<t.length;i++)if(t[i].left<t[i-1].right+2)return [t.length,false];return [t.length,true]})()")
    check('Body chart date labels do not collide at 360', ov[0]>=2 and ov[1], ov)
    for W in (320,390):
        pg.set_viewport_size({'width':W,'height':700}); pg.wait_for_timeout(200); pg.evaluate("renderProgressHome()")
        ov=pg.evaluate("(()=>{const t=[...document.querySelectorAll('svg[aria-labelledby=\"progBodyChart-sum\"] .ch-x')].map(e=>e.getBoundingClientRect());for(let i=1;i<t.length;i++)if(t[i].left<t[i-1].right+2)return [t.length,false];return [t.length,true]})()")
        check('Body chart date labels do not collide at %d'%W, ov[0]>=2 and ov[1], ov)
        check('no horizontal scroll at %d'%W, pg.evaluate("document.documentElement.scrollWidth<=innerWidth"))
    pg.set_viewport_size({'width':360,'height':700})
    check('older weight kept', pg.evaluate(BW).get('2026-11-01')==180)
    # backup and restore
    allw=pg.evaluate(BW); bk=pg.evaluate(EXPORT)
    check('backup carries every weight', json.loads(bk).get('bodyweight')==allw, json.loads(bk).get('bodyweight'))
    errs1=list(errs); ctx.close()
    ctx,pg,errs=page(b,360,700,seed=False); pg.on('dialog', lambda d: d.accept())
    pg.set_input_files('input[type=file][accept*=json] >> nth=0', files=[{'name':'b.json','mimeType':'application/json','buffer':bk.encode()}]); pg.wait_for_timeout(900)
    pg.evaluate("document.querySelectorAll('.settings-modal-overlay').forEach(m=>m.style.display='none')")
    check('restore keeps all weights', pg.evaluate(BW)==allw, pg.evaluate(BW))
    body(pg)
    check('restored weights listed on Body', len(pg.evaluate(ROWS))==min(5,len(allw)) and pg.evaluate("document.querySelector('#progView .prog-more')") is not None or len(allw)<=5)
    pg.reload(); pg.wait_for_timeout(1500); check('weights survive reload', pg.evaluate(BW)==allw)
    check('no page errors', not errs1 and not errs, errs1+errs); ctx.close()
    # tip on first visit to Body
    ctx,pg,errs=page(b,360,700,init="localStorage.setItem('monk_onboarded_v1','1');localStorage.setItem('monk_onboarding_complete_v1','true');localStorage.setItem('monk_tips_seen_v1',JSON.stringify({v:1,seen:{today:1,plan:1,lnote:1,wnote:1,quicklog:1,progress:1,run:1,food:1,style:1,menu:1}}));")
    go(pg,'calendar'); pg.wait_for_timeout(600)
    check('no Body tip on the Lifts view', not pg.evaluate("!!document.getElementById('tipBox')"))
    pg.click('#progTabBody'); pg.wait_for_timeout(200); pg.evaluate("tipSchedule(0)"); pg.wait_for_timeout(300)
    tip=pg.evaluate("(()=>{const t=document.getElementById('tipBox');return t?[t.innerText,t.nextElementSibling&&t.nextElementSibling.id]:null})()")
    check('Body tip shows once on first visit, by the form', tip and tip[0].startswith('Log your weight here any day. Past days work too.') and tip[1]=='bwForm', tip)
    txt='Log your weight here any day. Past days work too.'
    check('tip under 15 words, no dashes', len(txt.split())<15 and '-' not in txt and '—' not in txt)
    pg.click('#tipBox .tip-ok'); pg.wait_for_timeout(200)
    check('Got it stores the Body tip as seen', json.loads(pg.evaluate("localStorage.getItem('monk_tips_seen_v1')"))['seen'].get('body')==1)
    go(pg,'today'); go(pg,'calendar'); pg.evaluate("setProgView('lifts');setProgView('body');tipSchedule(0)"); pg.wait_for_timeout(400)
    check('Body tip never again after Got it', not pg.evaluate("!!document.getElementById('tipBox')") and pg.evaluate("loadTipsSeen().body")==1)
    check('backup includes the Body tip as seen', json.loads(pg.evaluate(EXPORT))['tipsSeen']['seen'].get('body')==1)
    check('no page errors (tip)', not errs, errs); ctx.close()
sys.exit(1 if done() else 0)
